-- Auction catalog expansion: append-only v2 content and rarity snapshots.

select 'ufc-auction-2026-08-v2',mode_id,item_reference,display_label,display_description,rarity_band,
  case
    when mode_id='ultimate-fighter' and display_label='Jon Jones' then 0.11
    when private_generation_class='ace' then 1.70
    when private_generation_class='headliner' then 0.70
    else generation_weight
  end, private_generation_class,grading_inputs
from private.auction_catalog where content_version='ufc-auction-2026-08-v1'
  and mode_id not in ('jon-jones-performances','conor-mcgregor-performances','charles-oliveira-performances');

-- Career banks are inserted directly so immutable catalog triggers never observe a DELETE.




-- Curated UFC-only additions retain v1 scores unchanged and use absolute v2 scores.

-- Final v2 weights are materialized by the original inserts; catalog rows are never mutated.

update private.auction_catalog_versions set is_preparation_version=false where is_preparation_version;
update private.auction_catalog_versions set is_preparation_version=true where content_version='ufc-auction-2026-08-v2';

do $$
declare
  v_expected jsonb := '{"ultimate-fighter":80,"jon-jones-performances":24,"conor-mcgregor-performances":14,"charles-oliveira-performances":37,"fighter-performances":64,"strikers":48,"grapplers":48,"knockout-artists":48,"greatest-ufc-card":64,"championship-performances":48,"finishes":64,"dominant-performances":48,"wars":48,"rivalries":48,"iconic-moments":64,"nicknames":64}'::jsonb;
  v_mode text; v_count integer;
begin
  for v_mode in select jsonb_object_keys(v_expected) loop
    select count(*) into v_count from private.auction_catalog where content_version='ufc-auction-2026-08-v2' and mode_id=v_mode;
    if v_count <> (v_expected->>v_mode)::integer then raise exception 'Auction v2 count mismatch for %: %',v_mode,v_count; end if;
  end loop;
  if exists (select 1 from private.auction_catalog where content_version='ufc-auction-2026-08-v2' and (jsonb_typeof(grading_inputs->'overall') <> 'number' or (grading_inputs->>'overall')::numeric not between 0 and 100)) then raise exception 'Auction v2 contains an invalid absolute score'; end if;
  if exists (select 1 from private.auction_catalog where content_version='ufc-auction-2026-08-v2' and mode_id='ultimate-fighter' and not (grading_inputs ?& array['Striking','Grappling','Frame','Power','Heart'])) then raise exception 'Auction v2 Ultimate Fighter category score is missing'; end if;
end $$;
